def compute_fixes_per_requirements(files: List[str], req_remediations:
    Iterator[Dict[str, Any]], auto_remediation_limit: List[str], prompt:
    bool=False) ->Dict[str, Any]:
    requirements = {
        'files': {},
        'dependencies': defaultdict(dict),
    }

    for file_obj in files:
        filename = getattr(file_obj, 'name', 'requirements.txt')
        content = file_obj.read()
        if isinstance(content, bytes):
            content = content.decode('utf-8')

        requirements['files'][filename] = {
            'content': content,
            'fixes': {
                'TO_SKIP': [],
                'TO_APPLY': [],
                'TO_CONFIRM': []
            },
            'supported': True,
            'filename': filename
        }

        reqs = read_requirements(content)
        for req in reqs:
            for remediation in req_remediations:
                if remediation and remediation.get('requirement'):
                    req_spec = str(remediation['requirement'].specifier)
                    if req_spec == str(req.specifier):
                        from_ver = remediation.get('version')
                        to_ver = remediation.get('recommended_version')

                        if from_ver and to_ver:
                            from_version = parse_version(from_ver) if isinstance(from_ver, str) else from_ver
                            to_version = to_ver if isinstance(to_ver, Version) else parse_version(str(to_ver))

                            if should_apply_auto_fix(from_version, to_version, auto_remediation_limit):
                                fix = Fix(
                                    previous_spec=req_spec,
                                    new_spec=f"{remediation['requirement'].name}=={to_version}",
                                    package=remediation['requirement'].name
                                )
                                requirements['files'][filename]['fixes']['TO_APPLY'].append(fix)
                            elif prompt:
                                requirements['files'][filename]['fixes']['TO_CONFIRM'].append(remediation)
                            else:
                                requirements['files'][filename]['fixes']['TO_SKIP'].append(remediation)

    return requirements
