def apply_fixes(requirements: Dict[str, Any], out_type: str, no_output:
    bool, prompt: bool, scan_flow: bool=False, auto_remediation_limit: List
    [str]=None) ->List[Fix]:
    applied_fixes = []

    for filename, file_info in requirements.get('files', {}).items():
        if not file_info.get('supported', False):
            continue

        content = file_info.get('content', '')
        if not content:
            continue

        fixes_to_apply = file_info.get('fixes', {}).get('TO_APPLY', [])

        for fix in fixes_to_apply:
            lines = content.split('\n')
            new_lines = []
            for line in lines:
                if fix.previous_spec in line:
                    new_lines.append(line.replace(fix.previous_spec, fix.new_spec))
                else:
                    new_lines.append(line)
            content = '\n'.join(new_lines)
            applied_fixes.append(fix)

        if fixes_to_apply and not no_output:
            if out_type == 'json':
                click.echo(json.dumps({'applied_fixes': [asdict(f) for f in applied_fixes]}))
            else:
                for fix in applied_fixes:
                    click.echo(get_applied_msg(fix))

        if filename != 'requirements.txt' or not hasattr(filename, 'write'):
            try:
                with open(filename, 'w') as f:
                    f.write(content)
            except Exception as e:
                LOG.error(f'Error writing fixes to {filename}: {e}')

    return applied_fixes
